/**
 * @suppress
 */
public object FfiConverterString: FfiConverter<String, RustBuffer.ByValue> {
    // Note: we don't inherit from FfiConverterRustBuffer, because we use a
    // special encoding when lowering/lifting.  We can use `RustBuffer.len` to
    // store our length and avoid writing it out to the buffer.
    override fun lift(value: RustBuffer.ByValue): String {
        try {
            val byteArr = ByteArray(value.len.toInt())
            value.asByteBuffer()!!.get(byteArr)
            return byteArr.toString(Charsets.UTF_8)
        } finally {
            RustBuffer.free(value)
        }
    }

    override fun read(buf: ByteBuffer): String {
        val len = buf.getInt()
        val byteArr = ByteArray(len)
        buf.get(byteArr)
        return byteArr.toString(Charsets.UTF_8)
    }

    fun toUtf8(value: String): ByteBuffer {
        // Make sure we don't have invalid UTF-16, check for lone surrogates.
        return Charsets.UTF_8.newEncoder().run {
            onMalformedInput(CodingErrorAction.REPORT)
            encode(CharBuffer.wrap(value))
        }
    }

    override fun lower(value: String): RustBuffer.ByValue {
        val byteBuf = toUtf8(value)
        // Ideally we'd pass these bytes to `ffi_bytebuffer_from_bytes`, but doing so would require us
        // to copy them into a JNA `Memory`. So we might as well directly copy them into a `RustBuffer`.
        val rbuf = RustBuffer.alloc(byteBuf.limit().toULong())
        rbuf.asByteBuffer()!!.put(byteBuf)
        return rbuf
    }

    // We aren't sure exactly how many bytes our string will be once it's UTF-8
    // encoded.  Allocate 3 bytes per UTF-16 code unit which will always be
    // enough.
    override fun allocationSize(value: String): ULong {
        val sizeForLength = 4UL
        val sizeForString = value.length.toULong() * 3UL
        return sizeForLength + sizeForString
    }

    override fun write(value: String, buf: ByteBuffer) {
        val byteBuf = toUtf8(value)
        buf.putInt(byteBuf.limit())
        buf.put(byteBuf)
    }
}



/**
 * One item of a `bulk_compress` result: the input's `index` and its
 * outcome. On success `ok` is true and `report` holds the result;
 * on failure `ok` is false, `report` is `null`, and the error is
 * carried flat in `error_code` / `error_message_en` /
 * `error_message_hi` (see DIVERGENCE note).
 */
data class BulkItemResult (
    var `index`: kotlin.UInt, 
    var `ok`: kotlin.Boolean, 
    var `report`: CompressReport? = null, 
    var `errorCode`: kotlin.String? = null, 
    var `errorMessageEn`: kotlin.String? = null, 
    var `errorMessageHi`: kotlin.String? = null
) {
    
    companion object
}

/**
 * @suppress
 */
public object FfiConverterTypeBulkItemResult: FfiConverterRustBuffer<BulkItemResult> {
    override fun read(buf: ByteBuffer): BulkItemResult {
        return BulkItemResult(
            FfiConverterUInt.read(buf),
            FfiConverterBoolean.read(buf),
            FfiConverterOptionalTypeCompressReport.read(buf),
            FfiConverterOptionalString.read(buf),
            FfiConverterOptionalString.read(buf),
            FfiConverterOptionalString.read(buf),
        )
    }

    override fun allocationSize(value: BulkItemResult) = (
            FfiConverterUInt.allocationSize(value.`index`) +
            FfiConverterBoolean.allocationSize(value.`ok`) +
            FfiConverterOptionalTypeCompressReport.allocationSize(value.`report`) +
            FfiConverterOptionalString.allocationSize(value.`errorCode`) +
            FfiConverterOptionalString.allocationSize(value.`errorMessageEn`) +
            FfiConverterOptionalString.allocationSize(value.`errorMessageHi`)
    )

    override fun write(value: BulkItemResult, buf: ByteBuffer) {
            FfiConverterUInt.write(value.`index`, buf)
            FfiConverterBoolean.write(value.`ok`, buf)
            FfiConverterOptionalTypeCompressReport.write(value.`report`, buf)
            FfiConverterOptionalString.write(value.`errorCode`, buf)
            FfiConverterOptionalString.write(value.`errorMessageEn`, buf)
            FfiConverterOptionalString.write(value.`errorMessageHi`, buf)
    }
}



/**
 * Pro compressor options (SPEC §2).
 */
data class CompressOptions (
    /**
     * Quality 1-100 (default 80). JPEG/WebP use it directly; PNG
     * uses `png_compression_level` + `palette` instead.
     */
    var `quality`: kotlin.UByte = 80u, 
    /**
     * Output format; `null` keeps the input format (TIFF input falls
     * back to PNG).
     */
    var `format`: ImageFormat? = null, 
    /**
     * Progressive JPEG / interlaced PNG (default false).
     */
    var `progressive`: kotlin.Boolean = false, 
    /**
     * Lossless output (WebP/PNG only; default false).
     */
    var `lossless`: kotlin.Boolean = false, 
    /**
     * Encoding effort: WebP 0-6, AVIF speed 0-10 (default 6).
     */
    var `effort`: kotlin.UByte = 6u, 
    /**
     * Chroma subsampling. `null` (default) = let the core apply the
     * quality-dependent rule: S420 for JPEG quality < 90, S444
     * otherwise (see DIVERGENCE note).
     */
    var `subsampling`: Subsampling? = null, 
    /**
     * PNG compression level 0-9 (default 6).
     */
    var `pngCompressionLevel`: kotlin.UByte = 6u, 
    /**
     * PNG quantise to palette (default false).
     */
    var `palette`: kotlin.Boolean = false, 
    /**
     * Preset; explicit fields override it (default unset).
     */
    var `preset`: Preset? = null, 
    /**
     * Target output size in bytes; same as `compress_to_size` via
     * one call (default unset).
     */
    var `targetBytes`: kotlin.ULong? = null, 
    /**
     * Downscale-only max width in px, aspect preserved, never
     * upscale (default unset).
     */
    var `maxWidth`: kotlin.UInt? = null, 
    /**
     * Downscale-only max height in px, aspect preserved, never
     * upscale (default unset).
     */
    var `maxHeight`: kotlin.UInt? = null, 
    /**
     * What metadata survives on output (default `All` = strip all).
     */
    var `stripMetadata`: StripMetadata = StripMetadata.ALL, 
    /**
     * Apply EXIF orientation on load (default true).
     */
    var `autoOrient`: kotlin.Boolean = true, 
    /**
     * DPI to write on JPEG/PNG output where supported
     * (default unset).
     */
    var `dpi`: Dpi? = null, 
    /**
     * Refuse images with more pixels than this (default 120,000,000).
     */
    var `maxPixels`: kotlin.ULong = 120000000uL, 
    /**
     * Refuse images with a side longer than this (default 16000).
     */
    var `maxDimension`: kotlin.UInt = 16000u
) {
    
    companion object
}

