            FfiConverterUByte.write(value.`pngCompressionLevel`, buf)
            FfiConverterBoolean.write(value.`palette`, buf)
            FfiConverterOptionalTypePreset.write(value.`preset`, buf)
            FfiConverterOptionalULong.write(value.`targetBytes`, buf)
            FfiConverterOptionalUInt.write(value.`maxWidth`, buf)
            FfiConverterOptionalUInt.write(value.`maxHeight`, buf)
            FfiConverterTypeStripMetadata.write(value.`stripMetadata`, buf)
            FfiConverterBoolean.write(value.`autoOrient`, buf)
            FfiConverterOptionalTypeDpi.write(value.`dpi`, buf)
            FfiConverterULong.write(value.`maxPixels`, buf)
            FfiConverterUInt.write(value.`maxDimension`, buf)
    }
}



/**
 * Full before/after report for one compression (SPEC §1).
 * `format` is the OUTPUT format. `saved_percent` is
 * `100 * saved_bytes / original_size` (0 when `original_size` is 0).
 * `quality_used` is the quality the output was actually encoded at
 * (differs from the requested quality after a `compress_to_size`
 * search or a downscale fallback). `resized` is true when the output
 * dimensions differ from the input dimensions.
 */
data class CompressReport (
    var `output`: List<kotlin.UByte>, 
    var `originalSize`: kotlin.ULong, 
    var `outputSize`: kotlin.ULong, 
    var `savedBytes`: kotlin.ULong, 
    var `savedPercent`: kotlin.Float, 
    var `format`: ImageFormat, 
    var `width`: kotlin.UInt, 
    var `height`: kotlin.UInt, 
    var `qualityUsed`: kotlin.UByte, 
    var `resized`: kotlin.Boolean
) {
    
    companion object
}

/**
 * @suppress
 */
public object FfiConverterTypeCompressReport: FfiConverterRustBuffer<CompressReport> {
    override fun read(buf: ByteBuffer): CompressReport {
        return CompressReport(
            FfiConverterSequenceUByte.read(buf),
            FfiConverterULong.read(buf),
            FfiConverterULong.read(buf),
            FfiConverterULong.read(buf),
            FfiConverterFloat.read(buf),
            FfiConverterTypeImageFormat.read(buf),
            FfiConverterUInt.read(buf),
            FfiConverterUInt.read(buf),
            FfiConverterUByte.read(buf),
            FfiConverterBoolean.read(buf),
        )
    }

    override fun allocationSize(value: CompressReport) = (
            FfiConverterSequenceUByte.allocationSize(value.`output`) +
            FfiConverterULong.allocationSize(value.`originalSize`) +
            FfiConverterULong.allocationSize(value.`outputSize`) +
            FfiConverterULong.allocationSize(value.`savedBytes`) +
            FfiConverterFloat.allocationSize(value.`savedPercent`) +
            FfiConverterTypeImageFormat.allocationSize(value.`format`) +
            FfiConverterUInt.allocationSize(value.`width`) +
            FfiConverterUInt.allocationSize(value.`height`) +
            FfiConverterUByte.allocationSize(value.`qualityUsed`) +
            FfiConverterBoolean.allocationSize(value.`resized`)
    )

    override fun write(value: CompressReport, buf: ByteBuffer) {
            FfiConverterSequenceUByte.write(value.`output`, buf)
            FfiConverterULong.write(value.`originalSize`, buf)
            FfiConverterULong.write(value.`outputSize`, buf)
            FfiConverterULong.write(value.`savedBytes`, buf)
            FfiConverterFloat.write(value.`savedPercent`, buf)
            FfiConverterTypeImageFormat.write(value.`format`, buf)
            FfiConverterUInt.write(value.`width`, buf)
            FfiConverterUInt.write(value.`height`, buf)
            FfiConverterUByte.write(value.`qualityUsed`, buf)
            FfiConverterBoolean.write(value.`resized`, buf)
    }
}



