sealed class DusimagezException: kotlin.Exception() {
    
    class InvalidImage(
        
        val `code`: kotlin.String, 
        
        val `messageEn`: kotlin.String, 
        
        val `messageHi`: kotlin.String
        ) : DusimagezException() {
        override val message
            get() = "code=${ `code` }, messageEn=${ `messageEn` }, messageHi=${ `messageHi` }"
    }
    
    class UnsupportedFormat(
        
        val `code`: kotlin.String, 
        
        val `messageEn`: kotlin.String, 
        
        val `messageHi`: kotlin.String
        ) : DusimagezException() {
        override val message
            get() = "code=${ `code` }, messageEn=${ `messageEn` }, messageHi=${ `messageHi` }"
    }
    
    class ImageTooLarge(
        
        val `code`: kotlin.String, 
        
        val `messageEn`: kotlin.String, 
        
        val `messageHi`: kotlin.String
        ) : DusimagezException() {
        override val message
            get() = "code=${ `code` }, messageEn=${ `messageEn` }, messageHi=${ `messageHi` }"
    }
    
    class TargetSizeUnreachable(
        
        val `code`: kotlin.String, 
        
        val `messageEn`: kotlin.String, 
        
        val `messageHi`: kotlin.String
        ) : DusimagezException() {
        override val message
            get() = "code=${ `code` }, messageEn=${ `messageEn` }, messageHi=${ `messageHi` }"
    }
    
    class InvalidQuality(
        
        val `code`: kotlin.String, 
        
        val `messageEn`: kotlin.String, 
        
        val `messageHi`: kotlin.String
        ) : DusimagezException() {
        override val message
            get() = "code=${ `code` }, messageEn=${ `messageEn` }, messageHi=${ `messageHi` }"
    }
    
    class InvalidDimensions(
        
        val `code`: kotlin.String, 
        
        val `messageEn`: kotlin.String, 
        
        val `messageHi`: kotlin.String
        ) : DusimagezException() {
        override val message
            get() = "code=${ `code` }, messageEn=${ `messageEn` }, messageHi=${ `messageHi` }"
    }
    
    class InvalidArgument(
        
        val `code`: kotlin.String, 
        
        val `messageEn`: kotlin.String, 
        
        val `messageHi`: kotlin.String
        ) : DusimagezException() {
        override val message
            get() = "code=${ `code` }, messageEn=${ `messageEn` }, messageHi=${ `messageHi` }"
    }
    
    class EmptyInput(
        
        val `code`: kotlin.String, 
        
        val `messageEn`: kotlin.String, 
        
        val `messageHi`: kotlin.String
        ) : DusimagezException() {
        override val message
            get() = "code=${ `code` }, messageEn=${ `messageEn` }, messageHi=${ `messageHi` }"
    }
    

    companion object ErrorHandler : UniffiRustCallStatusErrorHandler<DusimagezException> {
        override fun lift(error_buf: RustBuffer.ByValue): DusimagezException = FfiConverterTypeDusimagezError.lift(error_buf)
    }

    
}

/**
 * @suppress
 */
public object FfiConverterTypeDusimagezError : FfiConverterRustBuffer<DusimagezException> {
    override fun read(buf: ByteBuffer): DusimagezException {
        

        return when(buf.getInt()) {
            1 -> DusimagezException.InvalidImage(
                FfiConverterString.read(buf),
                FfiConverterString.read(buf),
                FfiConverterString.read(buf),
                )
            2 -> DusimagezException.UnsupportedFormat(
                FfiConverterString.read(buf),
                FfiConverterString.read(buf),
                FfiConverterString.read(buf),
                )
            3 -> DusimagezException.ImageTooLarge(
                FfiConverterString.read(buf),
                FfiConverterString.read(buf),
                FfiConverterString.read(buf),
                )
            4 -> DusimagezException.TargetSizeUnreachable(
                FfiConverterString.read(buf),
                FfiConverterString.read(buf),
                FfiConverterString.read(buf),
                )
            5 -> DusimagezException.InvalidQuality(
                FfiConverterString.read(buf),
                FfiConverterString.read(buf),
                FfiConverterString.read(buf),
                )
            6 -> DusimagezException.InvalidDimensions(
                FfiConverterString.read(buf),
                FfiConverterString.read(buf),
                FfiConverterString.read(buf),
                )
            7 -> DusimagezException.InvalidArgument(
                FfiConverterString.read(buf),
                FfiConverterString.read(buf),
                FfiConverterString.read(buf),
                )
            8 -> DusimagezException.EmptyInput(
                FfiConverterString.read(buf),
                FfiConverterString.read(buf),
                FfiConverterString.read(buf),
                )
            else -> throw RuntimeException("invalid error enum value, something is very wrong!!")
        }
    }

    override fun allocationSize(value: DusimagezException): ULong {
        return when(value) {
            is DusimagezException.InvalidImage -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterString.allocationSize(value.`code`)
                + FfiConverterString.allocationSize(value.`messageEn`)
                + FfiConverterString.allocationSize(value.`messageHi`)
            )
            is DusimagezException.UnsupportedFormat -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterString.allocationSize(value.`code`)
                + FfiConverterString.allocationSize(value.`messageEn`)
                + FfiConverterString.allocationSize(value.`messageHi`)
            )
            is DusimagezException.ImageTooLarge -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterString.allocationSize(value.`code`)
                + FfiConverterString.allocationSize(value.`messageEn`)
                + FfiConverterString.allocationSize(value.`messageHi`)
            )
            is DusimagezException.TargetSizeUnreachable -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterString.allocationSize(value.`code`)
                + FfiConverterString.allocationSize(value.`messageEn`)
                + FfiConverterString.allocationSize(value.`messageHi`)
            )
            is DusimagezException.InvalidQuality -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterString.allocationSize(value.`code`)
                + FfiConverterString.allocationSize(value.`messageEn`)
                + FfiConverterString.allocationSize(value.`messageHi`)
            )
            is DusimagezException.InvalidDimensions -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterString.allocationSize(value.`code`)
                + FfiConverterString.allocationSize(value.`messageEn`)
                + FfiConverterString.allocationSize(value.`messageHi`)
            )
            is DusimagezException.InvalidArgument -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterString.allocationSize(value.`code`)
                + FfiConverterString.allocationSize(value.`messageEn`)
                + FfiConverterString.allocationSize(value.`messageHi`)
            )
            is DusimagezException.EmptyInput -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterString.allocationSize(value.`code`)
                + FfiConverterString.allocationSize(value.`messageEn`)
                + FfiConverterString.allocationSize(value.`messageHi`)
            )
        }
    }

    override fun write(value: DusimagezException, buf: ByteBuffer) {
        when(value) {
            is DusimagezException.InvalidImage -> {
                buf.putInt(1)
                FfiConverterString.write(value.`code`, buf)
                FfiConverterString.write(value.`messageEn`, buf)
                FfiConverterString.write(value.`messageHi`, buf)
                Unit
            }
            is DusimagezException.UnsupportedFormat -> {
                buf.putInt(2)
                FfiConverterString.write(value.`code`, buf)
                FfiConverterString.write(value.`messageEn`, buf)
                FfiConverterString.write(value.`messageHi`, buf)
                Unit
            }
            is DusimagezException.ImageTooLarge -> {
                buf.putInt(3)
                FfiConverterString.write(value.`code`, buf)
                FfiConverterString.write(value.`messageEn`, buf)
                FfiConverterString.write(value.`messageHi`, buf)
                Unit
            }
            is DusimagezException.TargetSizeUnreachable -> {
                buf.putInt(4)
                FfiConverterString.write(value.`code`, buf)
                FfiConverterString.write(value.`messageEn`, buf)
                FfiConverterString.write(value.`messageHi`, buf)
                Unit
            }
            is DusimagezException.InvalidQuality -> {
                buf.putInt(5)
                FfiConverterString.write(value.`code`, buf)
                FfiConverterString.write(value.`messageEn`, buf)
                FfiConverterString.write(value.`messageHi`, buf)
                Unit
            }
            is DusimagezException.InvalidDimensions -> {
                buf.putInt(6)
                FfiConverterString.write(value.`code`, buf)
                FfiConverterString.write(value.`messageEn`, buf)
                FfiConverterString.write(value.`messageHi`, buf)
                Unit
            }
            is DusimagezException.InvalidArgument -> {
                buf.putInt(7)
                FfiConverterString.write(value.`code`, buf)
                FfiConverterString.write(value.`messageEn`, buf)
                FfiConverterString.write(value.`messageHi`, buf)
                Unit
            }
            is DusimagezException.EmptyInput -> {
                buf.putInt(8)
                FfiConverterString.write(value.`code`, buf)
                FfiConverterString.write(value.`messageEn`, buf)
                FfiConverterString.write(value.`messageHi`, buf)
                Unit
            }
        }.let { /* this makes the `when` an expression, which ensures it is exhaustive */ }
    }

}



/**
 * Output image format (SPEC §3). TIFF is deliberately absent: it is
 * an input-only format (it decodes, but is never an output format).
 */

enum class ImageFormat {
    
    JPEG,
    PNG,
    WEB_P,
    AVIF,
    GIF,
    BMP;
    companion object
}


/**
 * @suppress
 */
public object FfiConverterTypeImageFormat: FfiConverterRustBuffer<ImageFormat> {
    override fun read(buf: ByteBuffer) = try {
        ImageFormat.values()[buf.getInt() - 1]
    } catch (e: IndexOutOfBoundsException) {
        throw RuntimeException("invalid enum value, something is very wrong!!", e)
    }

    override fun allocationSize(value: ImageFormat) = 4UL

    override fun write(value: ImageFormat, buf: ByteBuffer) {
        buf.putInt(value.ordinal + 1)
    }
}





